/* Spielleitung (Grundbuch S. 104–120) – übersetzt */
window.HT_NACH = window.HT_NACH || {};
(function(){
function p(x, k){ return {t:"p", x:x, k:k ? 1 : 0}; }
function h(x){ return {t:"h", x:x}; }
function ul(a){ return {t:"ul", x:a}; }
function ks(h, a){ return {t:"kasten", h:h, b:a}; }
function K(a, n){ return {t:"karten", n:n || "4s", x:a.map(function(c){ return {t:c[0], b:[c[1]]}; })}; }
function G(n, cols){ return {t:"grid", n:n, x:cols}; }
window.HT_NACH.spielleitung = {t:"Spielleitung", p:104, subs:[
{id:"grundlagen", t:"Grundlagen", p:104, secs:[
 {id:"einleitung", t:"Einleitung", p:104, b:[
  p("Die anderen Spieler übernehmen die Rollen besessener Delver, die sich auf der Suche nach Antworten, Aufregung oder Erlösung in eine chaotische Welt stürzen. Sie werden die Stadt unter der Stadt erkunden und von ihrer Pracht gedemütigt werden; sie werden sich an den Felsen des roten, nassen Himmels zerschlagen, der unter der Erde schlummert."),
  p("Und du: Du bist dieser Himmel. Du baust Schritt für Schritt eine Welt auf, von der die Figuren nicht einmal wissen, dass sie sie wollen. Du bist der Herr über eine fremdartige, undurchschaubare Macht, die die reale Welt befällt und Unwirklichkeit in ihr verbreitet. Jeder schattige Tempel eines verbotenen Gottes, jede Vermissian-Station, deren Gleise singen, um die Ankunft nicht existierender Züge anzukündigen, jede verräucherte elende Spelunke, in der Händler ihre Waren anpreisen: Sie alle sind dein, um sie im Dienst der Spielerfiguren zu erschaffen und zu lenken."),
  p("Oder anders gesagt: Es ist ziemlich cool, in einer Heart-Kampagne Spielleitung zu sein."),
  p("In diesem Kapitel helfen wir dir, das bestmögliche Spiel zu leiten und dabei so viel Spaß wie möglich zu haben. Hoffentlich ist nichts von dem, was wir schreiben, Pflichtwissen, und du kannst auch ohne unsere Anleitung gut spielen, aber die hier beschriebenen Techniken und Tricks dürften trotzdem nützlich sein.")
 ]},
 {id:"erstes-mal", t:"Zum ersten Mal ein Rollenspiel leiten", p:104, b:[
  p("Hast du noch nie ein Spiel geleitet, ist dir vielleicht nicht bewusst, was alles dazugehört. Im Folgenden ein Überblick über die grundlegendsten Aufgaben einer Spielleitung; bist du darin schon bewandert, kannst du diesen Abschnitt überspringen und zum nächsten gehen."),
  G(2, [[
   p("Du bist in der Regel dafür zuständig, Spieler zum Spiel einzuladen. Du kannst Leute wählen, die du schon kennst und denen du vertraust, oder einen offenen Aufruf in einem Forum starten. Du brauchst mindestens eine weitere Person, um Heart zu spielen, sorge also dafür, dass du ein paar interessierte Spieler an der Hand hast."),
   p("Du bist auch dafür zuständig zu bestimmen, wo und wann das Spiel stattfindet. Viele Leute leiten ihre Spiele in Cafés oder Kneipen, besonders wenn sie in einer Großstadt leben und eines für alle Spieler gut erreichbar ist. Sonst nutzt du vielleicht dein Wohnzimmer oder ein freies Zimmer an deinem Arbeitsplatz oder deiner Schule/Universität (wenn sie es erlauben). Leitest du ein Online-Spiel, musst du die Plattform oder App wählen, auf der sich die Spieler treffen, und festlegen, wann das Spiel beginnt und endet."),
   p("Es ist deine Aufgabe, die Regeln parat zu haben und dafür zu sorgen, dass die Spieler Zugang dazu haben. Es ist toll, wenn Spieler ein eigenes Exemplar des Regelbuchs kaufen, aber nicht erforderlich. Charakterbögen zum Ausfüllen auszudrucken, wenn ihr persönlich spielt, ist nett, aber im Allgemeinen können Leute ihre Figuren auch auf Papier notieren, wenn du keine Zeit oder Lust hast. Sorge auch für die richtigen Würfel: ein paar W4, W6, W8, W12 und eine Handvoll W10."),
  ],[
   p("Während des Spiels bist du für alles zuständig außer den Handlungen der Spielerfiguren. Die meiste Zeit des Spiels läuft das als Gespräch zwischen dir und den Spielern. Du beschreibst die Welt und spielst die Nichtspielerfiguren, die Spieler reagieren als ihre Figuren, und du reagierst darauf. Du musst die Würfel nur herausholen, wenn eine Figur etwas versucht, das misslingen könnte."),
   p("Sind die Würfel gefallen (eine genauere Aufschlüsselung auf S. 8), liegt es an dir, die Ergebnisse zu deuten, die damit verbundenen Mechaniken anzuwenden (etwa Stress zuzufügen und auf Fallout zu prüfen) und die Ergebnisse in der Fiktion des Spiels zu beschreiben. Du bist die letzte Instanz für Regeln und Ereignisse des Spiels, aber frag ruhig die Spieler um Rat und Input, wenn sie dir helfen können."),
   p("Du bist auch für das Tempo des Spiels zuständig: die Energie über eine Sitzung hinweg im Fluss halten, den Spielern Momente hoher Intensität geben, sie sich entspannen lassen, eine Pause ausrufen und so weiter. Hoffentlich bekommst du schnell ein Gefühl dafür, was deinen Spielern Spaß macht.")
  ]])
 ]},
 {id:"tipps", t:"Allgemeine Tipps für Rollenspiele", p:105, b:[
  ul([
   "**Funktionieren die Regeln** für dich nicht, ändere sie ruhig. Es ist dein Spiel, und du solltest tun, was für dich und deine Gruppe funktioniert.",
   "**Hast du ein Problem** mit etwas, das ein Spieler tut, sprich ihn darauf an (am Tisch oder nach dem Spiel privat) und rede wie unter Erwachsenen mit ihm darüber. Ändert er sein Verhalten nicht, solltest du ihn aus dem Spiel nehmen. Es ist nicht deine Aufgabe, Leute zu besänftigen oder zu erziehen: Das hier ist eine Freizeitbeschäftigung.",
   "**Stelle den Spielern Fragen**, höre auf die Antworten und nutze sie, um das Spiel aufzubauen.",
   "**Lass die Spieler nur würfeln**, wenn etwas auf dem Spiel steht.",
   "**Nichts ist statisch.** Alles kann (und sollte) sich verändern, wenn die Spielerfiguren mit der Welt interagieren. NSC verändern sich und sterben. Landmarken entwickeln und verwandeln sich, wenn Leute ein- und ausziehen, Katastrophen sie zerreißen und die Bewohner ihre Spuren hinterlassen.",
   "**Beschreibst du** eine Person oder einen Ort, denke an alle verschiedenen Sinne. Riecht der Tempel nach rostigem Eisen und Meerwasser oder nach Zimt und Honig? Fühlt sich die Luft heiß und trocken auf der Haut der Spielerfiguren an oder klamm und nass? Können sie das Kratzen von Maschinen unter sich hören oder einen klagenden Trauergesang? Schmeckt das Weihwasser bitter und essigscharf oder erdig und mineralisch?",
   "**Spielst du** eine Nichtspielerfigur, kannst du viel tun, um sie interessant und fesselnd zu machen. Du kannst (und solltest!) verschiedene Stimmen und Eigenheiten verwenden, um sie von anderen abzuheben, aber du musst kein Meisterimitator sein – du kannst viel erreichen, indem du einfach Tonfall oder Stimmlage deiner Sprache veränderst. Du kannst auch deine Sitzhaltung ändern; schon kleine Änderungen der Haltung haben große Wirkung darauf, wie du aussiehst und klingst.",
   "**Aus irgendeinem Grund** scheinen viele Rollenspiele zu glauben, dass alle wie der Erzähler in einem Fantasyroman sprechen. Spielbeispiele lassen die Spielleitung Dinge sagen wie: „*Als ihr die unheilvolle Kammer betretet, spielt schillerndes Licht über eure abgetragenen Rüstungen, und der Priester sagt: ‚Seid gegrüßt, werte Herren, in diesem, dem bescheidensten Tempel Ihrer Unterirdischen Gnaden!‘*“ Das ist gelogen. So ziemlich jeder klingt eher so: „*Okay, also: ihr, äh, ihr geht in den Laden. Und er ist gruselig, und da sind so – leuchtende Lichter drin? Es ist scharf, wie eine klare Linie zwischen Licht und Schatten. Jedenfalls ist da ein Typ drin – ein Priester, komisch aussehender Typ – und er sagt: ‚Hallo! Komm rein in den Tempel!‘*“ Ein Gesprächston ist in Ordnung.",
   "**Jeder NSC sollte** etwas wollen, bei dem die Spielerfiguren helfen könnten, auch wenn er es nicht gleich sagt.",
   "**Deine NSC können lügen.** Niemand denkt daran, dass NSC lügen können. Spielerfiguren sind bemerkenswert leichtgläubig, und gelingt es dir richtig, wirkst du wie ein dramatischer Drahtzieher. Sorge aber dafür, dass sie durch das Lügen mehr zu gewinnen haben als durch die Wahrheit.",
   "**Nicht jeder** wird mit jedem anderen brillant rollenspielen. Manche Gruppen harmonieren einfach nicht, und niemand ist schuld. Spiele mit Leuten, die du magst und die mit dir eine brillante Geschichte aufbauen.",
   "**Lerne die Regeln** so gut du kannst. Du musst nicht wissen, was jede einzelne Fähigkeit tut, ohne nachzuschlagen (wir wissen es sicher nicht), aber je besser du die Regeln verstehst, desto flüssiger läuft das Spiel. Trotzdem brauchst du keine Angst zu haben, während des Spiels im Regelbuch nachzusehen – niemand erwartet, dass du alles in- und auswendig kennst.",
   "**Fällt es dir schwer**, herauszufinden, was als Nächstes passiert – besonders wenn deine Spieler etwas Unerwartetes tun –, ist es eine gute Idee, fünf Minuten Pause zu machen, um die Gedanken zu sammeln. Tatsächlich ist es auch dann gut, in der Mitte der Sitzung eine Pause einzuplanen, wenn du nicht ringst, damit du (und deine Spieler) frisch und engagiert bleiben.",
   "**Es gibt kein richtiges** oder falsches Leiten, und was für alle anderen funktioniert, funktioniert vielleicht nicht für dich. Je öfter du es tust, desto wohler wirst du dich fühlen."
  ])
 ]},
 {id:"story", t:"Zum ersten Mal ein Story-Spiel leiten", p:106, b:[
  p("Wir erklären unten, was „Story-Spiele“ sind; weißt du schon, was sie sind und was dich erwartet, kannst du zum nächsten Teil weitergehen. Andernfalls lies weiter!"),
  p("Das ist vielleicht eine unnötige Unterscheidung, aber Story-Spiele sind eine Art Rollenspiel, bei der erzählerische, thematische und figurengetriebene Elemente oft wichtiger sind als simulationistische. Persönlich denken wir, dass alle Rollenspiele Story-Spiele sind, da alle Rollenspiele dafür gemacht sind, eine Geschichte zu erzählen, selbst wenn sie nicht besonders fesselnd ist. Aber „Story-Spiel“ ist der Begriff, den wir haben."),
  p("Traditionelle (oder „Trad“-)Rollenspiele und Story-Spiele sind beide großartig, und wir sagen nicht, dass die eine Form besser ist als die andere oder dass du falschliegst, wenn du eine Art lieber magst. Hast du aber bisher nur Trad-Spiele gespielt, kann es schwerfallen, nachzuvollziehen, was nötig ist, um als Spielleitung in einem Story-Spiel zu gedeihen – hoffentlich hilft dir dieser Abschnitt dabei. Wie zuvor: Bist du in Story-Spielen bewandert, kannst du ihn überspringen und zum nächsten Teil gehen."),
  G(2, [[
   p("Story-Spiele sind beim Messen vager, als Trad-Spiele es sind. In traditionellen Spielen ist vieles streng definiert: die Länge eines Zuges, die Strecke, die eine Figur in diesem Zug zurücklegen kann, wie geschickt eine Figur mit einer bestimmten Waffenklasse ist, verschiedene Härtegrade von Türen und so weiter. Das lässt das Spiel flüssig laufen, weil alle wissen, was passiert und was im Rahmen der Regeln möglich ist. Die Mechaniken sind vielleicht schwer zu lernen, aber sind sie einmal da, nehmen sie viel Last bei der Verwaltung der Augenblicksereignisse eines Spiels ab."),
   p("Leitest du ein Story-Spiel, legst du die Welt als breiten Konsens fest. Es spielt nicht unbedingt eine Rolle, dass die Tür auf der anderen Seite der Kultisten, die dich jagen, 25 Meter entfernt eine steile Treppe hinauf liegt und die Lichtverhältnisse schattig sind. Zumindest bei Heart zählt, wie schwer es sein wird, dorthin zu kommen, und nicht, warum es so schwer ist. Die obige Situation klingt nach einem Riskanten **Evade**-Wurf; vielleicht auch nach zwei **Sneak**-Würfen mit Standardschwierigkeit, wenn du zwischen Deckungen hindurchhastest, statt mit Vollgas zu fliehen."),
   p("Tatsächlich spielt es keine Rolle, wie die Fluchtsituation aussieht, bis eine der Spielerfiguren sie in Betracht zieht. Sie existiert nicht, bis sie gebraucht wird. Sie braucht ganz sicher keine Regeln: Sie ist einfach das, was du willst und was sie für die Geschichte sein muss."),
   p("Du denkst darüber nach, wie Spielerfiguren mit einem Raum oder einer Situation interagieren und wie diese auf ihre Handlungen reagiert, statt eine Simulation aufzubauen und die Figuren darin existieren zu lassen: Es ist ein aktiver Prozess. Es ist deine Verantwortung, die „Simulation“ des Spiels zu betreiben, die in den Köpfen aller existiert, und das kann ziemlich auslaugend sein."),
   p("Als Spielleitung eines Story-Spiels wirst du viel öfter improvisieren und Entscheidungen treffen, als du es bei einem Trad-Spiel müsstest. Aus diesem Grund (unter anderem) empfehlen wir, Story-Spiel-Sitzungen zwischen 2 und 3 Stunden laufen zu lassen; sie kosten viel aktive geistige Energie. Natürlich sind du und deine Spieler vielleicht mit 10-stündigen Marathonsitzungen tief in der Stadt unter der Stadt einverstanden, und mehr Macht euch!")
  ],[
   p("Der zweite wichtige Punkt bei Story-Spielen hängt mit dem ersten zusammen: Das Fehlen von Simulation gibt dir die Macht, mühelos mechanisch zu improvisieren. Indem du die Zahl der Entscheidungen im Voraus verringerst und dich auf Begründungen und spielerzugewandte Regeln konzentrierst, schaffst du unendlich viele Ergebnisse für jede Handlung."),
   p("Story-Spiele mögen es, wenn du improvisierst; sie sind Maschinen zur Simulation von Momenten, die von der Erzählung zusammengehalten werden, keine lebendigen, atmenden Welten, die ihre Existenz außerhalb der Kamera aufrechterhalten. Weil sie darauf ausgelegt sind, Improvisation und Überraschung zu fördern, sind sie am besten, wenn du deine Sitzungen nicht zu sehr planst. Je mehr du festlegst, bevor die Spieler kommen, desto weniger flexibel bist du im Spiel. Statt auf das zu reagieren, was die Figuren tun, zwängst du Teile hinein, die du vorab vorbereitet hast. Das ist störend, unbefriedigend und ehrlich gesagt, wenn du schon vor Spielbeginn weißt, was passieren wird, warum leitest du dann ein Spiel? Du solltest stattdessen einen Roman schreiben und es dir von der Seele schreiben. Haben deine Spieler keine Chance, die Geschichte in eine neue, aufregende Form zu verwandeln, werden sie nicht viel Spaß haben."),
   p("Spiele (Story-Spiele besonders) sind am besten, wenn alle, die Spielleitung eingeschlossen, von dem überrascht sind, was geschieht. Außerdem – und das ist ein Geheimnis, sag es den Spielern nicht – sind Handlungsstränge, die spontan als Reaktion auf die Spieler entstehen, im Allgemeinen viel fesselnder und unterhaltsamer als im Voraus geschriebene. Durch Mitsprache an der Basis der Erzählung fühlen sich die Spieler beteiligt und freuen sich darauf, Dinge geschehen zu sehen, statt sich misstrauisch durch eine feste Geschichte zu bewegen."),
   p("Die beste Vorbereitung ist also, ein paar eindrucksvolle Konzepte und Motivationen aneinanderzureihen, auf die du zurückgreifen kannst, wenn Spieler neues Gebiet erkunden, und herauszufinden, wie du frühere Elemente wieder in die Erzählung einbaust. Dazu später mehr."),
   p("Der letzte wichtige Punkt bei Story-Spielen, der ebenfalls mit dem ersten zusammenhängt, ist, dass es schlicht nicht für alles Regeln gibt. Tatsächlich gibt es für die meisten Dinge keine Regeln. Das heißt, du wirst im Spielverlauf viele Entscheidungen ad hoc treffen. Wie das Erfinden einer Geschichte beim Erzählen kann das ziemlich auslaugend sein. Wo ein Trad-Spiel all diese Rechenleistung in die Regeln auslagert, bitten Story-Spiele die Spielleitung, diese Rolle zu übernehmen."),
   p("Bei Heart haben wir versucht, das so einfach wie möglich zu machen. Erstens brauchst du, solange du nicht mit einer Spielerfigur interagierst, überhaupt keine Regeln: Was auch immer du willst, geschieht einfach. Zweitens haben wir die Regeln, wenn du mit einer Spielerfigur interagierst, so flott gehalten, dass sich in jeder Situation binnen weniger Sekunden herausfinden lassen sollte, was zu tun ist. Fällt dir eine Regelentscheidung schwer, kannst du das Spiel ruhig anhalten oder die Spieler um Hilfe bitten. Du bist schließlich auch ein Spieler.")
  ]])
 ]},
 {id:"heart-erstmal", t:"Zum ersten Mal Heart leiten", p:107, b:[
  p("Okay – der Rest des Kapitels ist für dich. Wir tun unser Bestes, dich für das Leiten deiner eigenen Spiele voller Erkundung und Wahnsinn zu rüsten; aber vorher möchten wir ein paar Dinge aus dem Weg räumen."),
  p("Es gibt sehr, sehr viele verschiedene Denkschulen, wie man ein besserer Spielleiter wird. Manche empfehlen, so viele Regeln wie möglich zu lernen, damit man jede Situation sofort erfassen kann; manche sagen, der Schlüssel zum Erfolg sei, eine funktionierende Welt aufzubauen, in der die Spieler existieren können; andere behaupten, die beste Art sei, ein unparteiischer Schiedsrichter der Regeln zu sein, ein gleichgültiger, allmächtiger Gott."),
  p("Entscheidend ist: Keine davon ist richtig, und keine ist falsch. Nach ein paar Sitzungen wirst du herausfinden, was dir gefällt und was für dich und deine Gruppe am besten funktioniert, und dieser Stil wird sich mit der Zeit entwickeln."),
  p("Mit all diesen Vorbehalten: Hier ist, was unserer Meinung nach beim Leiten von Heart funktioniert, denn das tun wir gern, und wir haben das Spiel geschrieben, um es zu unterstützen. Funktioniert es für dich nicht, kannst du alles ignorieren und es selbst herausfinden. Es ist dein Spiel und deine Gruppe; du kennst sie besser als wir."),
  ks("Ich bin die Wand nicht hochgeklettert. Was ist passiert?", [
   "Einer deiner Spieler versucht, eine Wand hochzuklettern. Er will in den Hintereingang einer Landmarke einbrechen, wo er nach seinen Taten beim letzten Mal nicht mehr willkommen ist, aber er verpatzt seinen Wurf. Was passiert als Nächstes? Hier ein paar grobe Ideen:",
   ul(["„Du schaffst es auf einen Vorsprung auf halber Höhe, als sich dein Seil vom Dach löst und in die Dunkelheit unter dir stürzt. Markiere Stress bei Supplies.“","„Du klammerst dich volle drei Minuten reglos an die Wand, dein Herzschlag dröhnt in deinen Ohren, während du jemanden in der Nähe darüber reden hörst, was er mit dem letzten Kerl gemacht hat, den sie beim Einschleichen erwischt haben. Markiere Stress bei Mind.“","„Das bröckelnde Mauerwerk bricht, und du rutschst die Wand hinunter und landest hart. Markiere Stress bei Blood.“","„Du hörst Geschrei von oben, siehst jemanden auf der Mauer vor dem Licht der Siedlung als Silhouette und merkst zu spät, dass er dein Seil durchgesägt hat, und du fällst zu Boden. Markiere Stress bei Blood oder Fortune.“","„Auf halbem Weg nach oben siehst du einen Wachposten mit einem Gewehr, der auf der Mauer eine Rauchpause macht, ziemlich genau an der falschen Stelle. Markiere Stress bei Fortune.“"])
  ])
 ]},
 {id:"wichtigste", t:"Das Wichtigste", p:108, b:[
  h("Kampagnen-Rahmen"),
  p("Überlege, welche Art von Spiel dir und deinen Spielern gefallen würde. Hier einige Ideen für Heart-Spiele, die du leiten könntest:"),
  ul(["*Eine zusammengewürfelte Gruppe von Entdeckern, vom Schicksal zusammengeführt, delvt in die Stadt unter der Stadt auf der Suche nach Reichtum und um ihre eigenen besessenen Ziele zu verfolgen. (Das ist der „Standard“-Kampagnenrahmen für Heart.)*", "*Die Verteidiger eines Havens kämpfen darum, seine Bewohner am Leben und bei Verstand zu halten, während das Herz versucht, Gebiet zurückzuerobern.*", "*Ein geheimnisvoller Vorfahr hinterlässt dir ein verfallendes Herrenhaus in Derelictus, und du beschließt, in den Tunneln darunter einen Bergungsbetrieb aufzubauen – aber du bist schockiert über das, was du findest.*", "*Kannst du eine Handelsgesellschaft gründen und sie in der Stadt unter der Stadt überleben – vielleicht sogar gedeihen – lassen?*", "*Deine Führungsoffiziere haben dich verraten; verbrannt und gebrochen stolperst du ins Herz und willst dem Zorn jedes Spionageabwehr-Agenten in Spire entkommen.*", "*Deine Einheit wird entsandt, um einen wertvollen Gegenstand aus den Tiefen des Herzens zu bergen, aber auf dem Weg geht etwas schief.*", "*Eine Gruppe von Figuren mit der Berufung Penitent bricht zu einer großen Mission auf, um ihre Namen reinzuwaschen, nachdem sie in den Augen ihrer Kirche eine abscheuliche Sünde begangen haben.*", "*Eine Gruppe quijotesker Vermissian Knights und Deadwalker macht sich auf, die größten, gefährlichsten Kreaturen im ganzen Herzen zu jagen.*"]),
  h("Das Allerwichtigste"),
  p("Du bist der einzige Kontaktpunkt der Spieler zur Welt von Heart und der Schiedsrichter über ihren Erfolg und Misserfolg. Wenn du aus diesem Kapitel sonst nichts mitnimmst, merke dir dies:"),
  ks("", ["**Wenn die Spieler etwas tun, sollte sich die Welt dadurch verändern.**"]),
  p("Reagiert die Welt nicht auf die Handlungen der Spieler, können sie schnell frustriert sein und das Gefühl haben, nichts bewirken zu können. Als Spielleitung ist es deine Verantwortung, die fiktive Welt locker zu halten und dich nach dem Input zu verwandeln – wehre dich nicht gegen unerwartete Handlungen, indem du auf deinem Standpunkt beharrst. Deine Welt existiert in einem Zustand begrifflichen Flusses und verfestigt sich erst, wenn die Spielerfiguren ankommen und mit ihr interagieren. Fällt dir keine Möglichkeit ein, wie sich die Welt bei einem Fehlschlag verändert, lass die Spieler nicht würfeln, um zu sehen, was passiert."),
  p("Erfolgreiche Handlungen lassen sich meist leicht nutzen, um die Welt zu verändern: Sie sind ihrem Wesen nach die Spielerfigur, die versucht, Ereignisse zu ihren Gunsten zu beeinflussen. Ein Fehlschlag ist viel schwerer zu begründen, und es ist oft der erste Reflex einer Spielleitung, auf einen misslungenen Wurf mit Nichts zu reagieren. Die Handlung scheitert, die Welt verändert sich nicht, und alles geht weiter, als wäre es nie versucht worden."),
  p("Das ist enorm unbefriedigend. Es lässt Spieler sich machtlos fühlen (und nicht auf spaßige Art), es lässt ihre Figuren inkompetent wirken (was sie nicht sind), und es treibt die Geschichte nicht voran. Denk daran: Scheitert eine Spielerfigur bei einem Wurf, nimmt sie Stress. Was ist also geschehen, dass sie leidet? Welche Resistenz nimmt diesen Stress auf und riskiert Fallout? Sieh dir die Stressquellen auf S. 74 an und scheue dich nicht, kreativ zu sein."),
  p("Mach dir auch keine Sorgen, dass du zu hart zur Sache gehst. Heart ist ein Spiel über Unglück und Tragödie, und ein Großteil der Regeln ist dem Fallout gewidmet – er ist einer der aufregendsten Teile des Spiels. (Außerdem lieben es Spieler insgeheim, wenn ihren Figuren schlimme Dinge zustoßen. Es hat etwas Kathartisches.) Fallout ist ein Story-Beat: Er nimmt die vorangegangenen Ereignisse, verdichtet sie zu etwas Konkretem und Herausforderndem und drängt die Spieler, die daraus entstehenden neuen Probleme anzugehen.")
 ]}
]},
{id:"tipps-heart", t:"Tipps für Heart", p:109, secs:[
 {id:"planen", t:"Planung, Fragen, Wiederverwendung", p:109, b:[
  G(3, [[
   h("Hör auf zu planen"),
   p("Je mehr du eine Sitzung vorbereitest, desto mehr bereitest du dich auf ein Scheitern vor. Jede Entscheidung, die du triffst, bevor die Spieler da sind, bleibt festgeschrieben und wird brüchig – bestimmt, vielleicht, aber nicht Teil der gemeinsamen Geschichte, die du mit den Spielern teilst."),
   p("Die Spieler werden an solchen Entscheidungen anstoßen, und je härter sie drücken, desto leichter brechen sie. Entweder fällt die Planung auseinander, weil sie etwas getan haben, das du nicht erwartet hast, oder sie erkennen, dass sie passive Elemente in einer Welt sind, die mit etwas Vorherbestimmtem interagieren."),
   p("Flexibilität und Anpassungsfähigkeit sind der Schlüssel zum Erfolg. Denke bei der Vorbereitung in Figuren, groben Konzepten, Motivationen, Ideenfetzen, mit denen du spielen möchtest. Die Welt existiert nicht, bis du am Tisch über sie sprichst. Sicher, du hast vielleicht darüber nachgedacht – du hast es vielleicht sogar in ein Notizbuch geschrieben –, aber bis die Spieler mit ihr interagieren, ist sie völlig im Fluss. Die Spieler tauchen jede Woche auf und denken sich Dinge im Laufe des Spiels aus. Warum du nicht?"),
   p("Es ist beängstigend, als Spielleitung der Geschichte so zu vertrauen. Es gibt eine – echte oder eingebildete – Erwartung, dass du der unbezwingbare Herr einer erfundenen Welt bist, und einen instinktiven Drang, sich gegen Unerwartetes zu wehren, um die Kontrolle zu behalten. Das musst du nicht; die Geschichte wird sich schon fügen. Und wenn nicht? Okay. Du wirst dafür ja nicht bezahlt, und du kannst es immer wieder versuchen. Das hier ist nicht wichtig genug, um sich Sorgen zu machen, ob man es gut macht.")
  ],[
   h("Stelle Fragen"),
   p("Statt den Spielern eine sterile Welt vorzubereiten, an der sie abprallen, höre ihnen während der Sitzung zu. Stelle ihnen Fragen über die Welt, so wie sie dir Fragen stellen. Lass sie die Welt gemeinsam mit dir bauen. Hol sie als Co-Spielleiter ins Boot, wenn du willst: Spielt es so, dass ihr euch alle Dinge im Laufe des Spiels ausdenkt, ohne großes Geheimnis zu lösen oder Rätsel zu knacken – erzählt einfach gemeinsam eine Geschichte. Du bist schließlich nicht allmächtig."),
   p("Viele Fähigkeiten in Heart sind darauf ausgelegt, den Spielern zu erlauben, die Spielleitung zu überraschen. Der Vermissian Knight kann zum Beispiel erklären, dass sich in einer Landmarke eine Sekte von Okkultisten in der Nähe befindet, wenn er den Fortschritt **BLACK KNIGHT** genommen hat. Nutzen Spieler solche Fähigkeiten, frag sie (oder die anderen Spieler), welche Elemente sie einführen."),
   p("Offene Fragen sind in Ordnung – „Wie ist diese Sekte?“ gibt dem Spieler die Chance, seine kreativen Muskeln spielen zu lassen. Aber es gibt ihm nicht viel zum Arbeiten. Versuche stattdessen, Leitfragen zu stellen – solche, die den Spieler zu interessanten Entscheidungen über die Welt drängen. Beginne mit einer Aussage und bitte den Spieler, sie zu präzisieren. Hier einige Beispiele:"),
   ul(["*„Die Sekte hasst dich, bis auf ein Mitglied. Warum mag es dich?“*","*„Die Sekte ist sklavisch der Schaffung von Kunst ergeben. Was ist ihr neuestes Werk?“*","*„Die Sekte ist seltsam offen und freundlich. Was vermutest du, was sie im Schilde führen?“*","*„Du hast diese Leute noch nie getroffen – nur an sie geschrieben. Was erwartest du hier zu finden, und wie ist es völlig umgekehrt, wenn du Kontakt aufnimmst?“*","*„Die Sekte lässt Leute gern seltsame Riten vollführen, um aufgenommen zu werden. Was musstest du beim letzten Treffen tun?“*","*„Die Sekte ist viel zu eifrig. Was ist das eine, das du dir wünschst, dass sie nicht täten?“*"])
  ],[
   h("Setting-Details wiederverwenden"),
   p("Schreibe Dinge auf, wenn sie geschehen, nicht vorher. Notiere NSC-Namen und Motivationen, Orte, die die Figuren besuchen, Gegner, die du erfindest, Gerüchte über Delves – alles. Lass die Spieler es auch tun. Du schreibst alles auf, weil du es später verwenden wirst."),
   p("Führst du etwas ein, frag dich: „Kann ich etwas von früher wiederverwenden?“ Manchmal ist es schwierig, etwas bereits Existierendes mit der Geschichte zu verbinden, statt ein ganz neues Element zu erfinden, aber es ist viel befriedigender, wenn man es tut. Der menschliche Geist ist klein und berechenbar und tut sich schwer mit neuen Informationen. Taucht etwas mehr als einmal auf, ergibt es erzählerisch mehr Sinn als etwas Logisches, aber Unverbundenes, auch wenn wir uns alles im Laufe des Spiels ausdenken."),
   p("Du wirst nicht alles benutzen, was du aufschreibst – das sollst du auch nicht. Manches fällt im Spielverlauf von selbst unter den Tisch, und das ist in Ordnung. Es ist entbehrlich, kann aber als Ressource dienen, wenn du Mühe hast, die verstreuten Handlungsfäden zu einer interessanten Erzählung zu verknüpfen.")
  ]])
 ]},
 {id:"atmosphaere", t:"Atmosphäre erzeugen", p:110, b:[
  p("Hoffentlich entsteht die beabsichtigte Atmosphäre von Heart, wenn wir unsere Arbeit richtig gemacht haben, im Spiel ganz natürlich aus den Regeln. Aber um offen zu sein, zeigen wir unsere Überlegungen und sprechen über den Ton, den wir vermitteln wollten."),
  K([
   ["Wunder","Das Herz ist wunderbar, insofern es bei denen, die es erblicken, Staunen weckt. Portale zu fremden Himmeln nisten in einer Parasitendimension, die von einem neugierigen Intellekt beherrscht wird; unmögliche Himmel, besetzt mit fremden Sternen, erblühen unter der Erde; gottgleiche Wesen schlummern unruhig und warten darauf, durch Lobpreis oder Opfer geweckt zu werden. Je tiefer die Gruppe ins Herz hinabsteigt, desto seltsamer, großartiger und abstruser kannst du mit deinen Orten und Figuren werden. Werde so seltsam, wie du willst. Erweist sich ein Element als nicht tragfähig oder stört den Ton des Spiels, kannst du es immer von der Stadt unter der Stadt verschlingen lassen, um nie wieder gesehen zu werden."],
   ["Tragödie","Etwas Tragisches und Erbärmliches haftet den Kreaturen und Menschen im Herzen an. Wäre ihr Leben besser gelaufen, wären sie nicht hier; aber Ehrgeiz, Pech und Sturheit führen sie ins Verderben. Jedes Gebäude stürzt ein, und die Leute haben Angst, ihr Heim zu verlassen, falls sich die Pfade draußen neu anordnen und sie für immer in einer losen Tasche der Unwirklichkeit stranden lassen. Selbst die Monster sind krank, verängstigt und verzweifelt. Nichts und niemand, außer vielleicht dem Heart Itself, gewinnt dieses Spiel. Mach Erfolg vorübergehend, Siege pyrrhisch und Wohlstand bittersüß."],
   ["Horror","Wir reden uns ein, dass wir heilige Räume sind. Wir schützen und verehren unser Fleisch. Wir behaupten Herrschaft darüber. Wir sind getrennt von der Welt, und unsere Köpfe und Körper sind unsere Reiche. In einer Welt mit wenigen Zufluchten sind unsere Körper und Gehirne unser, um sie zu beherrschen und in ihnen Schutz zu suchen. Der Horror sagt uns: auf gar keinen Fall. Unsere Körper gehören nicht uns. Wir sind verletzliche, unvollkommene, zerbrechliche Wesen – vorübergehende Schmierflecken emporgekommenen elektrischen Fleisches. Unser Geist kann zerschmettert und neu geschmiedet werden und uns gegen uns selbst wenden. Die Welt ist riesig, komplex und jenseits unserer Kontrolle. Unsere Körper können durchstochen, aufgeschlitzt und verbrannt oder infiziert und verdorben werden. Es gibt keine Sicherheit, und nichts ist gewiss."],
   ["Menschlichkeit","Das Wichtigste an Heart ist, dass Menschen hier sind. (Auch wenn die Mehrheit dieser Menschen Elfen sind, benutzen wir „Menschlichkeit“ als Kurzform.) In dieser fremden Grenzregion, diesem unwirtlichen und wahnsinnigen Ort, tun Menschen ihr Bestes, um zu überleben und zu gedeihen. Nur sehr wenige der Leute, die in der Stadt unter der Stadt leben und arbeiten, sind das, was wir normal nennen würden, aber sie sind trotzdem Menschen und bieten eine willkommene Atempause vom Trommelfeuer aus Fleischkorridoren und fühlenden Zähnen. Im Kern kümmert sich das, was Menschen mehr als alles andere interessiert, um andere Menschen. Bring also Leute in dein Spiel: verängstigte Leute, überarbeitete Leute, gelangweilte Leute – Leute, die nicht alle Antworten haben und nicht die Kontrolle."]], 4)
 ]},
 {id:"unmenschlichkeit", t:"Unmenschlichkeit und Spannung", p:110, b:[
  h("Unmenschlichkeit"),
  p("Bei allem, was wir im vorigen Abschnitt sagten: Das Herz ist nicht für Menschen. Sie sollen nicht hier sein – sie sind Parasiten, Eindringlinge, die stehlen, was sie können, an einem Ort, den sie unmöglich verstehen können. Der Maßstab des Ortes ist völlig falsch, und er geht ewig weiter. Alles versucht, dich zu töten. Das Herz zu betreten ist wie das Betreten jeder anderen Wildnis: Entfernst du dich weit genug von den Strukturen, die wir zur gegenseitigen Stütze gebaut haben, fühlt sich bald selbst der egozentrischste Mensch winzig und unbedeutend."),
  p("Ja, das Herz hat sich um die Delver und andere Menschen, die es betraten, herum aufgebaut. Aber es ist nicht sehr gut darin. Es versteht sie nicht und kann sie vielleicht nicht verstehen. Dieser Ort ist für etwas gedacht, das mit der Menschheit nichts zu tun hat."),
  h("Spannung und wie man sie bricht"),
  p("Du wirst die Atmosphäre nicht das ganze Spiel über aufrechterhalten können. Das ist okay. Das sollst du auch nicht."),
  p("Heart ist als Horrorspiel gedacht: Es geht um gefährliche Leute, die aus schlechten Gründen unangenehme Dinge tun. Die Gegner und das Gelände reichen von beunruhigend bis verstörend, zu den Dingen, die deiner Figur schiefgehen können, gehören massenhaft invasive Körperverwandlungen, und selbst die Charakterfähigkeiten sind verstörend. Das Ganze trieft vor Horror."),
  p("Aber: Leute werden Witze machen und die Spannung des Körperhorror-Dungeon-Crawls durchbrechen. Sie machen Witze aus verschiedenen Gründen, zum Beispiel:"),
  ul(["Nervosität, ob in oder außerhalb der Rolle.","Um den Druck abzulassen, der sich in angespannten Horrorabschnitten aufbaut.","Weil etwas oft so übertrieben düster ist, dass es tatsächlich ziemlich komisch ist."]),
  p("Nichts davon ist an sich schlecht. Versuchst du, die Atmosphäre aus Wunder, Horror und Menschlichkeit angesichts der Unmenschlichkeit 100 % der Zeit aufrechtzuerhalten, werden deine Spieler erschöpft und frustriert sein. Lass Leute Witze machen und außerhalb der Rolle reden; lass sie herumalbern und den Horror-Gashebel zurücknehmen. Tatsächlich ist es noch wirkungsvoller, wieder in etwas Schreckliches zu krachen, wenn alle ein paar Sekunden zuvor schallend gelacht haben."),
  p("Verbringen sie das ganze Spiel damit, solltest du vielleicht über einen Wechsel zu einem anderen Spiel nachdenken (oder auch nicht, wenn ihr alle Spaß habt!). Aber im Allgemeinen spielt es keine Rolle.")
 ]},
 {id:"spieler", t:"Den Spielern geben, was sie wollen", p:111, b:[
  p("Im Grunde ist es deine Aufgabe als Spielleitung, die Geschichte auf interessante Weise zu lenken und die Spieler zufriedenzustellen. Die Beats, die an jede Berufung (siehe unten) geknüpft sind, sind dafür deine wichtigsten Werkzeuge, aber du kannst auch Informationen aus den Entscheidungen ziehen, die deine Gruppe bei ihren Figuren getroffen hat."),
  p("Sieh dir die Skills und Domains an, die die Spieler für ihre Figuren gewählt haben. Sie zeigen, dass sie wollen, dass ihre Figuren darin gut sind und sie im Spiel ausprobieren wollen. Gib den Spielern Gelegenheit, ihre Skills und Domains zu nutzen: Ein Spieler, der **Evade** und **Warren** gewählt hat, will, dass seine Figur von wahnsinnigen Kultisten durch ein enges Tunnelnetz gejagt wird, auch wenn seine Figur von der Idee nicht begeistert ist."),
  p("Ebenso sind die großen Fähigkeiten, die sie gewählt haben, ein Hinweis darauf, was sie sich wünschen. Wählt eine Witch **CRIMSON MIRROR** – eine Fähigkeit, die sie vorhersehen lässt, was auf Delves geschehen wird, und damit umzugehen –, signalisiert sie, dass sie auf Delves gehen und sie mitgestalten will. Wählt ein Vermissian Knight **DRAGON-KILLER**, will er wahrscheinlich Monster jagen."),
  p("Wenn du magst, notiere die großen Fähigkeiten, Skills und Domains jeder Figur und betrachte sie als deine Grundinspiration für eine Sitzung. Lenkst du das Abenteuer zu einem davon zurück, hat wahrscheinlich mindestens ein Spieler eine gute Zeit."),
  p("Einige der besten Informationen stammen jedoch aus Klasse und Berufung der Figuren. Berufungen werden etwas anders gehandhabt (siehe unten), aber hier eine grobe Aufschlüsselung dessen, was du je nach gewählter Klasse annehmen kannst, was Spieler in einem Spiel wollen:")
 ]},
 {id:"klassen", t:"Was Klassen wollen", p:112, b:[
  K([
   ["Cleaver","Gelegenheiten zu jagen und die Domains **Wild** und **Cursed** zu erkunden; halbwegs normale Leute, mit denen sie sich vergleichen können, um sich monströs zu fühlen; schwächere Gegner zum Terrorisieren und riesige Gegner, die sie mit vereinten Kräften zu Fall bringen; Körperhorror; Havens, in denen sie verstörend sein können, und Orte, an denen sie willkommen sind."],
   ["Deadwalker","Reisen; Mystik und Rituale; Geister und Untote; Anderswelten und Fractures; praktische Anwendungen religiöser Riten; seltsame Einsiedler treffen, die halbwegs nutzlose Weisheit verteilen; Dinge aus dem Himmel stehlen."],
   ["Deep Apiarist","Technologie, die so fortgeschritten ist, dass sie von Magie nicht zu unterscheiden ist; dem Chaos zu begegnen und zu versuchen, es zu kontrollieren; Strukturen zu schaffen und zu bauen; anderen zu helfen, auch wenn es die Leute gruselt, denen sie helfen; die Machenschaften des Heart Itself zu verstehen und zu bekämpfen."],
   ["Heretic","The Moon Beneath und der gleichnamige Tempel; seltsame Kulte und Sekten innerhalb der Damnic-Kirche, die man erkunden und ausnutzen kann; Religion und verschiedene Arten, mit dem Stress des Lebens in der Stadt unter der Stadt umzugehen; Gelegenheiten, hilfreich zu sein, und Gelegenheiten, seltsam zu sein, möglicherweise beides gleichzeitig."],
   ["Hound","Havens mit Problemen zu lösen; Leute, die etwas brauchen; sterbliche Sorgen, eine warme Mahlzeit und ein starker Drink; Wehrlose verteidigen, besonders wenn sie dabei eine Struktur verstärken können; den Erwartungen derer gerecht werden, die vor ihnen kamen."],
   ["Incarnadine","Fehlbare Leute mit begrenzter Macht und ausnutzbaren Schwächen; Verbindungen knüpfen und Havens stärken; mit Tölpeln reden und sie ausnutzen; Leute, die sie unterschätzen und dann ihre Quittung bekommen; Pläne, Schachzüge und Winkelzüge; die feineren Dinge des Lebens; Märkte, Händler und Geschäfte."],
   ["Junk Mage","Das Okkulte in all seinen Formen, besonders wenn diese Formen zum eigenen Vorteil genutzt werden können; eine Gelegenheit, ihre ganz speziellen Fähigkeiten einzusetzen (Gold essen, Wasser atmen, Stein wie Sand formen usw.); Ärger, vor dem man dramatisch davonlaufen oder den man listig umgehen kann; Wissensspeicher und verborgene Geheimnisse; jemand, der ihnen sagt, diese Magie sei Too Powerful For Them, fast wie eine Herausforderung."],
   ["Vermissian Knight","Seltsame und ungesehene Anblicke zu erkunden und zu bezeugen; andere zu beschützen, ob NSC oder Spielerfiguren; sich in die verdrehte Welt des Vermissian-Netzes zu wagen; uncanny Technologie zu finden und zu versuchen, sie zu nutzen; zu kämpfen und um Haaresbreite zu gewinnen."],
   ["Witch","Sich schlecht zu benehmen und Leute zu verstören; von NSC respektiert und gefürchtet zu werden; Abgesandte des Heart Itself zu treffen und sich an seinen Machenschaften zu beteiligen; ihre True Form am wirkungsvollsten Ort zu entfesseln; Heartsblood-Kreaturen zu treffen und sich mit ihnen zu verbinden."]], 3),
  p("Du musst dabei nicht verschämt sein. Oft ist Spielleiter-Rat darauf ausgerichtet, deine Absichten vor den Spielern zu verbergen und den Eindruck zu erwecken, du hättest eine riesige, vielschichtige, tickende Handlungsmaschine im Kopf, die sie nicht ganz sehen können. Aber du denkst dir ja alles nur aus, oder? Scheue dich also nicht, offen zu sprechen – „Ich glaube, ein Mordrätsel in der nächsten Landmarke würde Spaß machen, was meint ihr?“ –, denn keiner von uns wird jünger.")
 ]},
 {id:"beats", t:"Berufungen und Beats", p:112, b:[
  p("Das wichtigste Werkzeug, das dir als Spielleitung zur Verfügung steht, sind die Beats, die an die Berufungen der Spielerfiguren geknüpft sind: eine Liste von Szenen, Zielen, Ereignissen und Ausgängen, die sie wählen und zu erfüllen versuchen können. Tun sie das, lassen sie dich wissen, was mit ihrer Figur geschehen soll (auch wenn ihre Figur es vielleicht nicht will), also achte darauf."),
  p("Lass deine Spieler am Ende jeder Sitzung zwei Beats auswählen (oder biete ihnen die Chance, Beats zu ersetzen, die sie nicht mehr verfolgen wollen) und notiere, was sie wählen. Das bildet die Grundlage deiner Notizen für die Planung der nächsten Sitzung. Tatsächlich brauchst du vielleicht nicht mehr als das – aber bist du unsicher, ohne mehr Vorbereitung weiterzumachen, kannst du sie etwas ausarbeiten."),
  p("Ein großer Teil guter Spielleitung besteht darin, zu erahnen, was ein Spieler will, und es ihm zu geben. Wir haben versucht, den „Ahnungs“-Teil zu überspringen, und stattdessen zur Pflicht gemacht, dass jeder Spieler dir vor jeder Sitzung zwei Story-Beats nennt; dann belohnen wir die Spieler dafür, sie zu verfolgen. Es sollte hoffentlich ziemlich leicht sein, wie eine gute Spielleitung zu wirken, auch wenn du kaum Arbeit geleistet hast."),
  p("Wir erklären es genauer an einem Beispiel:"),
  p("*Die Delver haben es mit knapper Not zum Red Market geschafft, aber sie leben und sind größtenteils unversehrt. Sie sind auf einer Mission, die gegerbte und behandelte linke Hand eines Massenmörders zu stehlen, die im Anwesen von Rubious Crowfer zur Versteigerung steht. Die Beats, die die Spieler gewählt haben, und die möglichen Ereignisse, die helfen könnten, sie auszulösen, sind:*", true),
  ul([
   "*Leichten Blood-Fallout erleiden.* *Ein Kampf gegen zu Recht misstrauische Marktleibeigene (S. 193).*",
   "*Jemandes Leben verschonen.* *Einen der erwähnten Leibeigenen am Leben zu lassen, damit er seinem Herrn Bericht erstattet (oder nicht), könnte eine interessante Geschichte ergeben.*",
   "*Einen Puls aus erster Hand erleben.* *Triff die Delver mit einem Puls, während sie das Anwesen mit (oder ohne) die Hand verlassen. Der Markt beginnt sich zu heben und zusammenzuziehen, und frisches Wachstum sprießt zwischen den Pflastersteinen hervor. Noch besser, wenn es mit einem Fortune-Fallout-Ergebnis verbunden ist, aber nicht erforderlich.*",
   "*Einen Ritus an einem Ort der Macht vollführen (Tiefe 3 und tiefer).* *Der Red Market liegt auf Tiefe 2, also biete einen Weg zu einem tieferen Ort als mögliche Flucht, falls alles schiefgeht. Ein Delve hinab nach Ghastling Plain könnte gut funktionieren.*",
   "*Eine Ressource im Wert von mindestens W10 von einem gefährlichen Ort beanspruchen.* *Die Hand zu erlangen ist hier schon Belohnung genug. Erwähne unbedingt andere wertvolle Gegenstände, die zur Versteigerung stehen: einen singenden Kristallvogel, einen Bezoar von einem Himmelswal, eine gnollische Batterie-Dschinn aus Al'Marah usw.*",
   "*Einen dramatischen Auftritt hinlegen, der eine Riskante Handlung ist.* *Die Art Spieler, die diesen Beat wählt, wird sich ganz sicher selbst Gelegenheiten schaffen, ihn zu erfüllen – aber erwähne immer wieder große Fenster, schlecht gebaute Decken oder dünne Wände, durch die sie brechen können, wenn sie wollen.*"
  ])
 ]},
 {id:"bogen", t:"Charakterbögen, Zenith-Beats, gute Tode", p:113, b:[
  p("Der Großteil des Dramas in deinem Spiel entsteht daraus, dass die Spieler die Beats ihrer Figuren verfolgen. Sie sind so aufgebaut, dass sie zu einem Ende oder Zenith hinführen, an dem die Figur die Grenze ihrer Macht erreicht und beginnt, ihrem endgültigen Untergang entgegenzustolpern."),
  p("Der einfachste Weg, diese Beats als verbunden und als Teil eines befriedigenden Bogens wirken zu lassen, ist, sie miteinander zu verknüpfen – nicht nur mit anderen Beats derselben Figur, sondern auch mit denen anderer. Verwende so viel wie möglich wieder und baue auf dem auf, was zuvor war, und verändere es, statt jedes Mal etwas Neues zu erfinden."),
  p("Der Zenith-Beat einer Figur kündigt das Ende ihrer Geschichte an. Nach ein, zwei Sitzungen ist es eine gute Idee, dass die Spieler ihre verfügbaren Zenith-Fähigkeiten ansehen und eine auswählen, auf die sie hinarbeiten. Teilt dir ein Spieler mit, dass er seinen Zenith-Beat gewählt hat, solltest du ihm die Gelegenheit geben, in den nächsten Sitzungen darauf hinzuarbeiten. Fühlt sich die Auflösung unbefriedigend an, liegt es wahrscheinlich daran, dass er sie sich noch nicht verdient hat; füge der Handlung eine weitere Komplikationsebene hinzu und lass ihn weitermachen."),
  p("Erreicht ein Spieler den Zenith-Beat seiner Figur, kann er eine Zenith-Fähigkeit wählen: den ultimativen Ausdruck der Macht seiner Figur. Die meisten davon arbeiten mit Absolutem, setzen normale Regeln außer Kraft und geben dem Spieler viel kreative Macht. Auch wenn du die oberste Instanz des Spiels bleibst, solltest du ihnen beim Auflösen von Zenith-Fähigkeiten im Zweifel recht geben. Sie sind die Belohnung für all die Qual und das Unglück und geben dem Spieler die Chance, seine Figur im Gedächtnis derer zu verewigen, die am Spiel teilnehmen."),
  p("Die meisten Spielerfiguren werden jedoch keine Gelegenheit haben, ihren Zenith zu erreichen, da sie vorher kritischen Fallout erleiden und aus dem Spiel genommen werden. Im Spielverlauf häuft sich der Fallout an – auch wenn es immer an der Spielleitung liegt, zwei schwere Fallouts zu einem kritischen zu kombinieren, gibt es einen Punkt, an dem es unvermeidlich wirken kann. Erinnere deine Spieler daran, dass das Ziel dieses Spiels nicht ist zu gewinnen, sondern eine gute Geschichte zu erzählen. Manchmal ist der Tod Teil dieser Geschichte."),
  p("Heart ist nicht die Art Spiel, in der man jahrelang dieselbe Figur spielen kann. Sie sind zerbrechliche, wandelbare, vorübergehende Dinge, die du ermutigt wirst, in Aufregung, Abenteuer und Unglück zu werfen. Sie werden sterben. Sie sollen sterben. Wenn es so weit ist, lass den Spieler seiner Figur einen würdigen Abschied geben und die vergebliche Tragik seines tödlichen Ehrgeizes wirklich spürbar machen – oder gib ihm die Chance, den Tag zu retten und einen letzten verzweifelten Versuch zu machen, anderen zu helfen, bevor der Schnitter ihn holt.")
 ]},
 {id:"kampagne", t:"Kampagnen, One-Shots, Delver-Arbeit", p:114, b:[
  G(3, [[
   h("Eine Kampagne beenden und eine neue beginnen"),
   p("Heart ist als System für kurze Kampagnen gedacht. Die ideale Länge einer Kampagne (zumindest nach unserer Ansicht) beträgt etwa acht verbundene Spiele. Figuren sind nicht dafür gebaut, jahrelanges Spielen auszuhalten, wie oben erwähnt, und das Tempo des Spiels und der Abstraktionsgrad der Regeln bedeuten, dass Ereignisse recht schnell geschehen können."),
   p("Während dein Spiel Form annimmt, solltest du anfangen, darüber nachzudenken, wie es enden wird. Im Allgemeinen solltest du nach etwa drei Sitzungen einen Höhepunkt ausarbeiten können. Mach dir keine Gedanken, was die Spielerfiguren tun werden; arbeite stattdessen etwas aus, das sie wollen (als Gruppe oder einzeln), und erfinde jemanden oder etwas, das sie davon abhalten will. Während die Spielerfiguren ihre Berufungen durchlaufen, bringe sie in Konflikt mit der Opposition und steuere auf eine letzte Konfrontation zu, in der sie bekommen, was sie wollen (oder tragisch daran scheitern)."),
   p("Sobald das geschieht, kannst du die „Kampagne“ als beendet betrachten: Die Geschichte ist erzählt. Rufe eine Pause im Spiel aus, nimm dir eine Woche frei und lass alle zur Ruhe kommen. Sind die Leute interessiert, biete ihnen die Chance, erneut zu spielen, mit denselben Figuren oder mit neuen. Nimm dann deine Karte (S. 208), wähle einen neuen Eingangspunkt auf Tiefe 0 und gehe wie gewohnt nach unten. Besuche alte Landmarken und Delves erneut, um zu erkunden, wie sie sich verändert haben, seit die Spielerfiguren zuletzt dort waren, während du eine neue Geschichte in deiner ständig wachsenden Version des Herzens erzählst.")
  ],[
   h("One-Shots"),
   p("Nicht jeder hat die Zeit oder Geduld, eine Kampagne zu leiten. Gehörst du dazu oder willst du Heart nur ausprobieren, um zu sehen, wie es sich anfühlt, ohne dich auf ein regelmäßiges Spiel festzulegen, kannst du das Spiel als One-Shot leiten: ein Erlebnis in einer einzigen Sitzung, das in etwa drei oder vier Stunden Aufregung und Drama bieten soll."),
   p("Heart als One-Shot zu leiten ist recht einfach. Die einzigen Änderungen betreffen das Tempo und wie du Stress und Fallout zufügst."),
   p("Beim Tempo: Streiche alle langatmigen Teile, bei denen ihr alle wisst, wie sie ausgehen. Lass kein Treffen aufbauen, um einen Auftrag für die Delver auszuhandeln. Springe stattdessen direkt zu dem Punkt, an dem sie zu einem Delve aufgebrochen sind und die Dinge dramatisch schiefzulaufen begonnen haben. Gib ein klares Ziel vor, das in einer einzigen Spielsitzung lösbar ist, und baue eine Wendung ein, die eine knifflige Entscheidung oder eine interessante Herausforderung bietet. Gib deinen Spielern zuletzt vier oder fünf Beats zur Auswahl und überlege, wie du helfen kannst, sie während der Sitzung zu erfüllen, und es kann losgehen."),
   p("Beim Stress: Tu ihnen weh. Es ist nicht nötig, auf Nummer sicher zu gehen, Fallout zu erhalten macht Spaß, und die Spieler müssen sich nicht darum sorgen, dass ihre Figuren bis zur nächsten Sitzung überleben. Lass Situationen außer Kontrolle geraten, zerstöre Landmarken, töte NSC und spiele das Spiel im Schnelldurchlauf. Es ist ein anderes Erlebnis als eine Kampagne und ebenso lohnend.")
  ],[
   h("Delver-Arbeit"),
   p("Ein Großteil der Handlung wird von den Figuren geliefert, während sie ihre Beats durchlaufen, aber es hilft, ein übergeordnetes Ziel zu haben, das sie vereint. Aus diesem Grund sollten deine NSC den Spielerfiguren Arbeit anbieten – viele der Landmarken (S. 130) haben Beschäftigungsmöglichkeiten."),
   p("Aufträge sollten die Spielerfiguren in ungewöhnliche und gefährliche Situationen bringen, sie interessanten NSC begegnen lassen und ihnen die Gelegenheit geben, die einzigartige Welt der Stadt unter der Stadt zu erkunden."),
   p("Der naheliegendste Weg, den Spielerfiguren Aufträge zu geben, ist, es in der Rolle eines NSC zu tun, der etwas erledigt haben will. Aber fühle dich nicht auf diesen Ansatz beschränkt – hier ein paar weitere Ideen."),
   ul(["*Frage die Spieler direkt, welche Arbeit sie bisher getan haben, um über Wasser zu bleiben, und wo (oder von wem) sie normalerweise Aufträge bekommen. Mache eine leicht andere Version dieses Auftrags und biete sie ihnen an.*","*Viele der Beats, die mit Berufungen verbunden sind (besonders der Berufung Forced), drehen sich um das Erfüllen von Missionen, also warte, bis deine Spieler direkt um eine bitten, und mach sie schrecklich. Oder lass sie dir sagen, was die Mission ist, und mach sie dann schrecklich.*","*Beginne jedes Abenteuer in medias res und nenne den Auftrag außerhalb der Rolle – „Als ihr euch dem Deathshead-Tempel nähert, auf der Suche nach heiligen Motten für die Mutter Oberin, hört ihr aus seinem Inneren das untrügliche Geräusch einer gesungenen Mordballade. Was tut ihr?“*","*Mache den Spielerfiguren zwischen Spielen, wenn sie in einer Landmarke sind, Angebote per E-Mail oder Direktnachricht und lass sie auswählen, was sie vor Sitzungsbeginn interessiert.*","*Alle Arbeitsanfragen kommen anonym auf geheimnisvollen Papierschnipseln und werden verdächtig gut bezahlt.*"])
  ]])
 ]}
]},
{id:"nsc-kampf", t:"NSC und Kampf", p:116, secs:[
 {id:"nsc", t:"Nichtspielerfiguren erschaffen", p:116, b:[
  p("Als Spielleitung spielst du jede Nichtspielerfigur im Spiel. Glaubst du, dass die Spieler versuchen werden, gegen eine Figur zu kämpfen, brauchst du Werte für sie – such etwas Passendes aus dem Kapitel Adversaries aus und passe es an. Ist ein Kampf aber unwahrscheinlich, musst du dir um die Mechanik keine Gedanken machen und kannst dich darauf konzentrieren, eine interessante Figur zu machen."),
  p("Hier ein paar Dinge, die du beim Erstellen und Spielen einer Nichtspielerfigur bedenken kannst:"),
  ul([
   "**Gib ihnen einen Namen.** Menschen schöpfen aus walisischen, kornischen und (seltsamerweise) griechischen Namen; Drow nutzen altertümliche französische und haitianische Namen mit veränderten Buchstaben; Aelfir haben Ketten poetischer Bilder als Namen, die ein wenig wie Haiku klingen; Gnolls schöpfen aus nahöstlichen Namen oder kombinieren einfach zwei coole Substantive. Fällt dir kein Name ein, nimm Wörter, deren Klang du magst (Insouciance, Cavalcade, Bellicose, Ventricle, Shank, Tryst, Spurious) und geh davon aus.",
   "**Wisse, was sie jetzt wollen** und vielleicht, was sie im großen Ganzen wollen (aber das Erste ist viel wichtiger), und vermittle das den Figuren.",
   "**Du bist (wahrscheinlich)** kein professioneller Schauspieler und kannst nicht proben, mach dir also keine Gedanken um Feinheiten oder zarte Nuancen bei deinen Nichtspielerfiguren. Schreibe und spiele sie groß und kräftig, übertreibe das Schauspiel und scheue dich nicht, die Handlung „versehentlich“ auszuplaudern.",
   "**Mit wem ist die Figur verbunden?** Welchen Organisationen oder Fraktionen, die in deiner Geschichte schon etabliert sind, könnte sie angehören? Im Allgemeinen wirkt deine Welt umso befriedigender, je mehr du Leute miteinander verknüpfst – und sind die Spieler grausam oder beleidigend zu einem NSC, hilft es, wenn jemand ihn unterstützt, um den Einsatz zu erhöhen.",
   "**Sei nicht kokett**, gib keine vagen Antworten, weil du einen Zauberer im Film das einmal tun gesehen hast, und tu nicht geheimnisvoll. Das ist frustrierend, und Spielern gefällt es nicht. Finde stattdessen etwas, worüber der NSC unbedingt mit den Spielern reden will, und geh davon aus.",
   "**Finde heraus, was sie aus der Masse hervorhebt.** Wenn die meisten Leute ihres Ordens X sind, ist dieser Kerl Y, z. B.: „Die meisten Retroengineers sind zappelig und besessen; dieser Kerl schläft in seiner Werkstatt, obwohl er von einem halben Dutzend leerer Kafee-Tassen umgeben ist.“",
   "**Lass deine Figuren sich verändern** (statische Figuren sind langweilig). Das gilt nicht nur langfristig, wenn sie sich als Reaktion auf Ereignisse entwickeln, sondern auch innerhalb einer Szene. Betrittst du eine Szene glücklich, versuche sie traurig zu verlassen und umgekehrt. Zeigst du eine reiche Figur, ist es interessant zu sehen, wie sie ihr ganzes Geld verliert; und mächtige Figuren, die gestürzt werden (oder Figuren von niedrigem Stand, die aufsteigen), sind immer interessant.",
   "**Gib deinen Figuren Schwächen und Marotten;** auch wenn sie unmenschlich aussehen, gib den Spielern ein Element von Menschlichkeit, an das sie anknüpfen und das sie verstehen können. (Das gilt nur für NSC, die sprechen können; einem Heartsblood-Bären musst du kein menschliches Element geben. Andererseits könnte es gruselig sein, also erwäge es.)",
   "**Wähle eine Eigenheit** und zieh sie hart durch. Auch Schlagworte sind gut. Du zielst auf Charakterisierung auf Wrestling-Profi-Niveau, nicht auf die Hauptfigur einer siebenstaffeligen HBO-Serie. Versuche, deinen Punkt in zehn Sekunden oder weniger rüberzubringen.",
   "**Scheue dich nicht, sie zu töten.** Jede Figur ist entbehrlich, Nichtspielerfiguren doppelt. Die Geschichte geht weiter, auch wenn dein Lieblings-NSC tot ist, und sie profitiert vielleicht sogar davon (besonders wenn die Spielerfiguren schuld an seinem Tod sind)."
  ])
 ]},
 {id:"kampf", t:"Über Kampf", p:116, b:[
  p("Das Herz ist ein gefährlicher Ort. Dort gibt es viele Leute, die haben wollen, was du hast, und sie schrecken nicht davor zurück, dich dafür zu töten. Es gibt unzählige Bestien, die nach Fleisch hungern. Es gibt Kulte, die dich liebend gern einsperren und deine abenteuerlustige Seele Stück für Stück abschöpfen würden, bis du eine verdorrte Hülle bist."),
  p("Rollenspiele sind eng mit Kampf verbunden; fast jedes Spiel hat Regeln dafür, oder sie haben vielleicht nur Regeln dafür. Tatsächlich hat jede einzelne Klasse in Heart mindestens eine Handvoll Tricks, mit denen sie ihre Kampfstärke erhöhen kann – sei es beim Angreifen, Verteidigen, Heilen, Steigern der Macht anderer oder Kontrollieren des Schlachtfelds."),
  p("Aber: Nicht alles muss ein Kampf sein. Kämpfe sind brutal und können sehr schnell in tödliche Verletzungen kippen. Figuren können Fallout außerhalb von Haunts nur in seltenen Fällen heilen, und selbst dann müssen sie dafür bezahlen. Schwerer **Blood**-Fallout könnte das Todesurteil für die Laufbahn eines Delvers sein."),
  p("Kämpfe sind grausam, weil beide Seiten einander Schaden zufügen, um ihren Willen durchzusetzen. Sprichst du ein Problem mit jemandem durch, kannst du ihn später vielleicht als Verbündeten nutzen. Erstichst du ihn, musst du dich mit seinen aufgebrachten Freunden und Verwandten oder der drohenden Lynchjustiz mit einem leeräugigen Hound an der Spitze herumschlagen."),
  p("Kämpfe lassen wenig Raum für Verhandlungen, und es ist immer leichter zu eskalieren als zu deeskalieren. Du kannst niemanden un-morden (außer mit einer Zenith-Fähigkeit, und selbst die kommt mit vielen Bedingungen) oder jemanden dazu bringen, ruhig zu reden und einen vernünftigen Handel zu schließen, nachdem du seinen Partner in die Brust geschossen hast."),
  p("Aus all diesen und weiteren Gründen: Lass deine Spieler ihre Kämpfe wählen."),
  ul(["**Erstens:** Überlege, was die Gegner wollen und warum es sie dazu gebracht hat, die Spielerfiguren anzugreifen. Alle Gegner haben aus diesem Grund einen Abschnitt Motivation in ihrem Wertekasten. Es ist höchst unwahrscheinlich, dass ihr wahrer Wunsch ein Kampf auf Leben und Tod mit ein paar Sonderlingen ist, die gerade in ihr Gebiet gewandert sind. Die meisten Leute und Kreaturen kämpfen, weil sie ihren gesellschaftlichen Stand wahren, einem Schwächeren Ressourcen abnehmen (Nahrung, Wertsachen, Handelsrouten) oder das behalten wollen, was sie als ihr Gebiet betrachten. Wie hart werden die Gegner kämpfen, um zu bekommen, was sie wollen, und zu behalten, was sie haben?","**Zweitens:** Gib den Spielern viele Informationen. Gib ihnen die Gelegenheit, die Typen zu bemerken, die kommen, um ihnen die Beute zu rauben, die sie in den Tiefen des Herzens aufgelesen haben. Zeige ihnen die Spuren und Fährten des Heartsblood-Ungetüms, das im lichtlosen Tal unter ihnen blubbert und fault. Lass einen Gesandten des Kults, den sie verärgert haben, kommen und ihnen sagen, sie sollen die Grabungsstätte verlassen, um Blutvergießen zu vermeiden.","**Drittens:** Gib den Spielerfiguren einen Ausweg. Können sie ihren Feinden ganz ausweichen? Können sie aus einem brennenden Haven fliehen, statt dem Gemetzel durch einen abtrünnigen Hound-Trupp ausgesetzt zu sein? Können sie ihren Feinden einfach geben, was sie wollen? Können sie sie zu einem Kompromiss überreden? Können sie sie austricksen, ihre Waffen niederzulegen, oder sie in die Flucht schrecken?"]),
  p("Spieler fühlen sich nicht so schlecht behandelt, wenn ihr Unglück selbstverschuldet ist. Ein False Hallow, der mitten in einem Delve auftaucht und mit illegaler Magie ein tellergroßes Loch in jemandes Rücken sprengt, fühlt sich vielleicht etwas billig an. Hatten sie die Gelegenheit, den Kerl vorher auszukundschaften – vielleicht einen Auftrag vom Tempel von The Moon Beneath anzunehmen, ihn zum Schweigen zu bringen, die Tür seines schmuddeligen Tempels einzutreten und dann ein erhebliches Stück ihres Rückenfleisches zu verlieren, während er einen hektischen Fluch ausspuckt –, fühlt es sich besser an, obwohl es mechanisch dasselbe ist."),
  p("Wollen deine Spieler trotzdem kämpfen, so gibst du es ihnen:")
 ]},
 {id:"kampf-planen", t:"Ausgewogene Begegnungen", p:117, b:[
  p("Begegnungen sind nicht ausgewogen, also wirf diese Idee ganz über Bord."),
  p("*(Okay. Du willst trotzdem einen fairen Kampf? Das ist nicht diese Art Spiel. Aber eine Spielerfigur kann im Durchschnitt 4 Stress pro Handlung austeilen, also: Nimm die Zahl der Handlungen, die der Kampf dauern soll, multipliziere sie mit 4 und such Gegner mit einer Gesamt-Resistance in dieser Höhe aus. Schutzwerte, Schwierigkeit und Waffen mit hohem Schaden auf beiden Seiten bringen das allerdings völlig aus dem Gleichgewicht.)*", true),
  p("Was willst du mit diesen Gegnern hervorrufen? Was sagen sie über dein Herz aus? Ist der Kannibalenkult, der die Schwachen und Gebrechlichen von den Straßen von Derelictus pflückt, eine gewaltige, mächtige Verschwörung mit mutierten Fußsoldaten in angeschraubten Rüstungen, oder sind sie verzweifelte Aasfresser, die in Hinterhöfen und verlassenen Kellern einen fremden Hunger stillen wollen? Beides funktioniert."),
  p("Sind deine Spieler scharf darauf, eine Schlägerei anzufangen? Gib sie ihnen! Hast du einen Deadwalker, einen Vermissian Knight und einen Hound, die alle zur Monsterjagd gerüstet sind, dann gib ihnen große gefährliche Monster zum Bekämpfen. Lass sie es zu ihren eigenen Bedingungen tun. Ist ein Monster gefährlich, sage gleich, dass es gefährlich ist, und lass sie eine informierte Entscheidung treffen, ob sie es angehen."),
  p("Hetzt du dieselben Monster auf eine Incarnadine, einen Deep Apiarist und eine Witch, hast du ein ganz anderes Erlebnis. Sie sind schlicht nicht darauf vorbereitet, genauso wie die Monsterjäger nicht unbedingt darauf vorbereitet sind, einen Friedensvertrag zwischen zwei verfeindeten Kirchen auszuhandeln und eine Handelsroute zu einer Siedlung voller hungernder Menschen zu öffnen."),
  p("Ermutige die Spieler, das Spielfeld auszugleichen oder die Lage sogar zu ihren Gunsten zu kippen – vergib Mastery-Würfel, verringere eingehenden Stress oder senke die Schwierigkeit des Gegners, wenn du meinst, dass sie unterhaltsame Vorbereitungen getroffen haben. In manchen Fällen haben Gegner Schwächen, die den Kampf fast trivial machen können – das Nutzen des speziellen Bane eines Geistes (S. 187) etwa entfernt seinen Schutzwert und erhöht den gegen ihn zugefügten Stress um zwei Stufen. Das hat das Potenzial, einen sonst tödlichen Kampf mit einem einzigen Wurf zu lösen, und das ist gut (solange allen das Recherchieren und Vorbereiten der Banes Spaß gemacht hat)."),
  p("Such dir aus, was du interessant findest, gib den Spielern die Möglichkeit, dagegen zu kämpfen, und schau, was passiert.")
 ]},
 {id:"kampf-zu", t:"Kampf zu schwer oder zu leicht", p:118, b:[
  G(2, [[
   h("Was tun, wenn ein Kampf zu schwer ist"),
   ul(["Der Gegner nimmt, was er von der Situation wollte, und geht.","Der Gegner hat Mitleid mit den Delvern und fügt nur schweren Fallout zu, bevor er kichernd davonspaziert.","Nutze ein Fortune-Fallout-Ergebnis, um das Eintreffen von etwas noch Gefährlicherem auszulösen – es verscheucht den ursprünglichen Gegner und gibt den Delvern eine Chance zur Flucht.","Enthülle eine bisher nicht erwähnte Schwäche (anhaltende Verletzung, wahnhafte Hingabe, Fehlen bestimmter Sinne), die die Delver für mehr Schaden oder Würfe mit niedrigerer Schwierigkeit ausnutzen können.","Erinnere die Spieler daran, dass sie weglaufen können, auch wenn es heißt, etwas zurückzulassen.","Lass einen Verbündeten am Schauplatz eintreffen, um die Spielerfiguren zu unterstützen.","Nimm willkürlich die Hälfte der Resistance des Gegners weg oder „vergiss“, seinen Schutz vom eingehenden Stress abzuziehen, und sag es niemandem."])
  ],[
   h("Was tun, wenn ein Kampf zu leicht ist"),
   ul(["Lass die Spieler sich schlecht dabei fühlen, diese verletzlichen Kreaturen zu verletzen.","Lass die Gegner aufgeben und weglaufen.","Kündige das Eintreffen weiterer Gegner als Verstärkung an, falls mit diesen nicht fertig geworden wird.","Lass einen der Gegner eine gefährliche Waffe ziehen und damit ihre Bedrohung erhöhen.","Zeige, dass die Gegner nur ein Ablenkungsmanöver waren und die Delver nun ein neues Problem lösen müssen.","Lass die Gegner schreckliche übernatürliche Merkmale zeigen (Homunculi erbrechen, mit ihren Gedanken Abgründe in die Erde reißen, Reißzähne, die von dimensionsspaltendem Gift triefen, beim Tod in Schwärme von Dingen zerfallen), erhöhe ihren Schaden und Schutz entsprechend und begründe es später."])
  ]]),
  ks("Gewöhnliche Leute", ["Wollen die Spieler aus irgendeinem Grund gegen normale Leute kämpfen (nun ja, so „normal“, wie sie im Herzen werden), haben die meisten Leute Resistance 5. Sind sie unbewaffnet, fügen sie W4 Schaden zu, und greifen sie nach einer Waffe, fügen sie W6 zu."])
 ]},
 {id:"kampf-szenen", t:"Kampfszenen verbessern", p:118, b:[
  ul([
   "**Haben deine Gegner** Namen haben können, gib ihnen Namen. Dafür ist der Abschnitt Namen im Wertekasten da! Ebenso sollte jeder Gegner anders als die anderen sein. Kannst du sie nicht ausreichend unterscheiden oder sind es zu viele, fasse sie zu einer einzigen Einheit zusammen (siehe Mobs auf S. XX) und geh davon aus.",
   "**Habe nie einen Kampf**, nur um einen Kampf zu haben. Jeder Kampf sollte um etwas gehen, und nicht jeder Kampf sollte auf Leben und Tod sein.",
   "**Können deine Gegner reden**, lass sie reden. Sprechen sie mit den Spielerfiguren, miteinander, darüber, was sie tun werden, und reagieren sie auf das Geschehene. Mach dir keine Sorgen, dabei zu offensichtlich zu klingen: Du fügst Farbe hinzu und verstärkst, dass die Handlungen der Spieler Auswirkungen auf die Spielwelt haben, du versuchst nicht, dein Opus magnum zu schreiben. Sachen wie „Sie kommen die Treppe hoch, wirf mir eine Waffe zu!“ und „Gavain ist verletzt, ruft Hilfe!“ sind in Ordnung.",
   "**Lass echte Verletzungen** selten und brutal sein. Zum Beispiel: **Blood**-Stress sind Beulen, blaue Flecken, Schürfwunden, Atemnot, Beinahe-Treffer, Erschöpfung, Paraden, die Erschütterungen durch deine Knochen schicken, der Geschmack von Blech im Mund und so weiter. **Blood**-Fallout ist Reißen, Verdrehen, Zerren, Schießen, weißglühender scharfer Schmerz, das fremde Gefühl von kaltem Metall, das dein warmes Fleisch durchsticht, Zähne, die in deinem Mund zersplittern, schnell abkühlendes Blut, das Hose und Socken durchtränkt, usw.",
   "**Frage die Spieler:** „Wie sieht das aus?“, nachdem sie einen Wurf gemacht haben. Lass sie den Fluss des Kampfes beschreiben, während er fortschreitet, und stärke ihre Figur, indem du ihr etwas Fokuszeit gibst.",
   "**Sage Spielern nie**, dass ihre Figuren Angst haben, selbst wenn sie mit einem gebrochenen Bein verbluten und von hungrigen Rasiermesserzahn-Egeln umgeben sind. Sie hassen es, gesagt zu bekommen, dass sie Angst haben, und meistens spielen sie als Reaktion darauf, doppelt hart zu sein und vor nichts Angst zu haben, also lass sie selbst entscheiden, wie sie sich fühlen (bis der **Mind**-Fallout einsetzt, jedenfalls).",
   "**Stelle Dinge in den Weg.** Figuren können in Deckung gehen (nicht dass es in den Regeln wirklich vorkäme, aber es ist nett, es manchmal zu sagen), Leute in Hindernisse treten, Requisiten greifen, um sie als Einmalwaffen zu nutzen, Ablenkungen schaffen – alles, um das Gefühl zu durchbrechen, dass ihr in einem merkmalslosen Raum kämpft.",
   "**Spiele mit Position und Raum.** Lass Gegner Figuren packen und herumschleudern – es ist ja alles nur Beschreibung, du kannst also sagen, was du willst, solange es nicht die Art Inhalt ist, die dem Fallout vorbehalten ist. Es ist interessanter, eine Treppe hinuntergestoßen zu werden, als einen Kinnhaken zu bekommen, und mechanisch haben sie dieselbe Wirkung. Lass Wände und Böden bröckeln und neue Bereiche zum Verprügeln enthüllen.",
   "**Lass Leute die Regeln** für jede Waffe nutzen, die sie besitzen, egal welchen Angriff sie beschreiben. Alles andere fördert sich wiederholende und langweilige Beschreibungen, weil Spieler gern den größtmöglichen Schaden anrichten. Zum Beispiel: Hat jemand ein Schwert (**Kill W6**) und will einen armen Kerl in einem Brunnen ertränken (**Kill W4**), kannst du ihn genauso gut einen W6 für Stress würfeln lassen; jemanden in einem Brunnen zu ertränken nutzt ein Element der Szene und ist wahrscheinlich einprägsamer und persönlicher als ein Hieb mit einer Klinge.",
   "**Zieh einen Kampf nicht länger hin**, als du musst. Haben die Spieler ihre Gegner in der Zange, beende ihn dort. Die Feinde geben auf, versuchen zu fliehen oder fangen an zu verhandeln. Es muss nicht zu einer Würfelübung verkommen.",
   "**Steckt ein Spieler** eine Menge Punkte in **Blood**-Schutz, will er oft getroffen werden, also triff ihn und lass ihn seine Fähigkeiten zeigen. Damit er aber bescheiden bleibt, bring ab und zu einen Gegner ein, der **Mind**- oder **Echo**-Stress zufügt, oder lass **Fortune**-Stress auf ihn niedergehen, wenn er einen Wurf verpatzt, damit er sich nicht ganz unverwundbar fühlt. Alle Rüstung der Welt hilft dir nicht, wenn du in ein Loch fällst."
  ])
 ]}
]},
{id:"landmarken-delves", t:"Landmarken und Delves", p:119, secs:[
 {id:"landmarken", t:"Landmarken und Delves", p:119, b:[
  p("Das Herz ist voller Geheimnisse, und der Großteil dieser Geheimnisse sammelt sich in Landmarken. Wir möchten zunächst ein paar Dinge aus dem Weg räumen, was die Auswahl von Landmarken für deine Kampagne betrifft."),
  G(3, [[
   h("Du musst nicht alle nutzen"),
   p("Das sollst du auch nicht – sie sind nicht alle da! Deine Version des Herzens wird eine Handvoll der Landmarken oder ganz eigene Schöpfungen haben, die durch Delves verbunden sind. Such die aus, die du interessant findest oder die den Interessen deiner Spielerfiguren dienen, und geh davon aus.")
  ],[
   h("Du musst sie nicht wie geschrieben nutzen"),
   p("Verändere sie – nimm Elemente aus der einen und schiebe sie in eine andere. Tausche die Domains gegen andere aus und schau, wie es sich anfühlt. Tauschst du zum Beispiel die Domains **Occult** und **Haven** in Hallow (S. XX) gegen **Religion** und **Wild**, bekommst du ein ganz anderes Bild davon, wie Witches in der Stadt unter der Stadt arbeiten.")
  ],[
   h("Du musst dir auch nicht alle merken"),
   p("Und das ist entscheidend: Das hier ist keine Lore-Bibel, die du lernen musst, bevor du das Spiel leiten darfst, und besonders die Landmarken sind als Inspiration für deine eigenen Schöpfungen gedacht. Alles hier ist gemeinschaftlich – erinnern sich deine Spieler an eine coole Landmarke aus dem Spiel, die du nicht kennst, frag sie nach Details und bau sie ein. Du bist nicht verpflichtet, mehr über das Setting zu wissen als jeder andere, denn das Setting existiert nicht, bis es an deinem Tisch auftaucht.")
  ]]),
  h("Delves"),
  p("Delves können wir in diesem Buch nicht liefern, da sie spezifisch für deine Geschichte sind – wir können nicht vorhersagen, wie die Landmarken in deinem Herzen angeordnet sein werden. Zum Glück haben wir im Abschnitt Delves auf S. 133 eine Anleitung dafür geschrieben. Haben die Spieler viele delve-lastige Fähigkeiten gewählt, ist das für dich ein Zeichen, dass sie an Reisen, Erkundung und Entdeckung interessiert sind. Du kannst ruhig viele schöne, lange Delves mit hoher Resistance einbauen. Haben sie diese Fähigkeiten dagegen nicht, solltest du Verbindungen oder alternative Routen anbieten, die sie mit anderen Skills nutzen können – Kampf, Überzeugung, Tricks usw."),
  p("Du musst nicht jeden Teil eines Delves ausarbeiten – nur die interessanten. So wie ein Film keine Stunde ereignislosen Reisens zeigt, tust du es auch nicht."),
  p("Wichtig: Delves sind keine Rätsel, die man lösen muss. Es gibt keine richtige oder falsche Route für die Spieler; vielmehr ist es eine Reihe von Herausforderungen, die ihnen Gelegenheit bieten, ihre Fähigkeiten zu zeigen. Stelle Probleme ohne Lösung im Kopf und lass die Spieler die Feinheiten klären.")
 ]},
 {id:"abschluss", t:"Zum Abschluss", p:120, b:[
  p("Machst du dir Sorgen, dein erstes (oder zweites oder zwanzigstes) Spiel von Heart zu leiten, haben wir eine gute und eine schlechte Nachricht für dich:"),
  p("Es geht nie weg. Wir haben das System geschrieben, und wir sind fast jedes Mal nervös, wenn unsere Spieler zu einer Sitzung auftauchen. Heart so zu leiten, wie wir es tun – und wie wir es dir in diesem Kapitel raten –, ist eine Übung im Vertrauen. Die Gruppe vertraut darauf, dass du eine aufregende Geschichte entwickelst, und du vertraust im Gegenzug darauf, dass sie deine Autorität respektiert. Ihr alle vertraut darauf, dass ihr die Geschichte vorwärts, rückwärts oder in welche interessante Richtung auch immer treibt."),
  p("Es gibt viele bewegliche Teile und viel Rätselraten, und manchmal geht es schief. Das ist okay. Würde nie etwas schiefgehen, würdest du nie etwas lernen und dich nie verbessern. Im großen Ganzen spielt es keine Rolle, wenn eine Sitzung abstürzt und verbrennt; es wird andere Sitzungen und andere Spiele geben."),
  p("Du musst darin nicht gut sein, auch wenn du es als Hobby gewählt hast. Besser zu werden fühlt sich gut an, aber du bist nicht verpflichtet, dich zu verbessern. Du und die Spieler müsst nur Spaß haben.")
 ]}
]}
]};
})();
